node --input-type=module --eval "
import {ToolRegistry} from './dist/orchestration/tools/registry.js';

const registry = new ToolRegistry();
registry.register(
  {
    name: 'test',
    description: 'Test',
    inputSchema: {
      type: 'object',
      properties: {userId: {type: 'string'}},
      required: ['userId'],
    },
  },
  async () => 'success'
);

(async () => {
  const response = await registry.execute('test', {userId: 12345});
  console.log('Result:', response.result);
  console.log('Includes userId:', response.result.includes('userId'));
  console.log('Includes string:', response.result.includes('string'));
})();
